actions.script:
const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
let settings = storeHost ? {storeKind: storeKind, storeSecurity: storeSecurity, storeHost: storeHost, storePort: storePort, smtpHost: smtpHost,
    smtpPort: smtpPort, smtpSecurity: smtpSecurity, mailUsername: mailUsername, source: source || 'guess'} : null
hasPassword = false
let kind = accountKindEnumId
let address = emailAddress
let suggestion = null
if (emailAccountId) {
    const detail = ec.service.sync().name('ironstone.MailSettingsServices.get#MailAccountDetail').parameter('emailAccountId', emailAccountId).call()
    if (!ec.message.hasError() && detail?.found) {
        hasPassword = detail.server?.hasPassword === true
        if (!settings && detail.server) settings = Object.assign({source: 'saved'}, detail.server)
        if (!address) address = detail.account?.emailAddress
        kind = detail.account?.accountKindEnumId || kind
    }
}
if (!settings && address) {
    suggestion = ec.service.sync().name('ironstone.MailSettingsServices.suggest#MailServer').parameter('emailAddress', address).call()?.suggestion || null
    if (suggestion) settings = suggestion
}
hasAddress = !!address
if (!hasAddress) return
settings = settings || {}
const provider = ec.service.sync().name('ironstone.MailSettingsServices.get#MailProvider').parameters({emailAddress: address,
    storeHost: settings.storeHost || null}).call()?.provider || null
const SOURCES = {provider: L('IronStone knows the server settings of your provider.'), autoconfig: L('Your mail provider publishes these server settings.'),
    ispdb: L('These server settings are from the Thunderbird database of mail providers.'), srv: L('These server settings are from the DNS records of your domain.'),
    saved: L('These are the server settings saved with the account.'),
    guess: L('These server settings are guesses from your domain: check them against your provider\'s help page for mail apps (IMAP and SMTP).'),
    failed: L('The server settings could not be looked up just now, so these are guesses: check them against your provider\'s help page.')}
const sourceKey = SOURCES[settings.source] ? settings.source : 'guess'
sourceText = SOURCES[sourceKey]
isGuess = sourceKey === 'guess' || sourceKey === 'failed'
providerName = provider?.providerName || null
appPassword = provider?.appPassword === true
helpText = provider?.helpText || null
helpUrl = provider?.helpUrl || null
helpLinkText = provider?.helpLinkText || L('Where to make it')
noteText = provider?.noteText || null
warningText = suggestion?.warningText || (provider?.unsupported ? provider.helpText : null)
passwordTitle = appPassword ? L('App password') : L('Password')
passwordCaption = hasPassword ? L('Saved. Leave it empty to keep it, or enter a new one.')
    : (appPassword ? ec.resource.expand('The app password you made for ${name}; it is kept encrypted and never shown again.', '', {name: providerName})
        : L('Your email password; it is kept encrypted and never shown again.'))
connect = {emailAccountId: emailAccountId || '', emailAddress: address, displayName: displayName || '', accountKindEnumId: kind || 'EakExternal',
    storeKind: settings.storeKind || 'imap', storeSecurity: settings.storeSecurity || 'ssl', storeHost: settings.storeHost || '',
    storePort: settings.storePort || '', smtpHost: settings.smtpHost || '', smtpPort: settings.smtpPort || '',
    smtpSecurity: settings.smtpSecurity || 'starttls', mailUsername: settings.mailUsername || address, mailPassword: ''}
